namespace Inventory;

/// <summary>
/// Coordinates cycle counting, discrepancy reconciliation, and inventory valuation.
/// </summary>
public sealed class CycleCountService
{
    private readonly CycleCountLedger _countLedger = new();
    private readonly DiscrepancyTracker _discrepancyTracker = new();
    private readonly InventoryValuationLedger _valuationLedger = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _countLedger.Record(item, warehouse, counted, _valuationLedger);

    public int CountVariance(StockItem item) =>
        _countLedger.GetVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancyTracker.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancyTracker.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuationLedger.Update(item, unitCost);
}

internal sealed class CycleCountLedger
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);

    public string Record(
        StockItem item,
        Warehouse warehouse,
        int counted,
        InventoryValuationLedger valuationLedger)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        valuationLedger.RecordVariance(item.Sku, variance);
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int GetVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        if (variance < 0)
            return variance;
        return variance;
    }
}

internal sealed class DiscrepancyTracker
{
    private readonly List<string> _discrepancies = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        var available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            _discrepancies.Add($"{item.Sku}:oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            _discrepancies.Add($"{item.Sku}:negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            _discrepancies.Add($"{item.Sku}:phantom-reserve");
            return "phantom";
        }

        if (available > 0 && available < 5)
            _discrepancies.Add($"{item.Sku}:low");
        else if (available > 10000)
            _discrepancies.Add($"{item.Sku}:excess");

        return _discrepancies.Count > 1000
            ? "too many discrepancies"
            : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;

        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;

        var tag = Classify(reason);
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        if (tag == "critical" && _discrepancies.Count > 0)
            return true;
        return tag != "note";
    }

    private static string Classify(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}

internal sealed class InventoryValuationLedger
{
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public void RecordVariance(string sku, int variance)
    {
        _valuations[sku] = variance > 0
            ? variance * 2.0m
            : variance * 1.0m;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;

        var basisQuantity = GetBasisQuantity(item);
        var value = basisQuantity * unitCost;
        if (value > 1_000_000m)
            value = 1_000_000m;
        else if (value < 0m)
            value = 0m;

        _valuations[item.Sku] = value;
        if (basisQuantity == 0 || unitCost == 0m)
            return 0m;
        return value;
    }

    private static int GetBasisQuantity(StockItem item)
    {
        if (item.ReorderPoint > 0 && item.OnHand > item.ReorderPoint)
            return item.OnHand;
        if (item.OnHand > 0)
            return item.OnHand;
        return 0;
    }
}
